package io.knowledgebrain.notification;
import java.time.*;import java.sql.Timestamp;import java.util.*;import java.nio.charset.StandardCharsets;import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import tools.jackson.databind.json.JsonMapper;import io.knowledgebrain.contracts.notification.groupreview.v1.*;
final class GroupReviewStore {
 record Access(UUID groupId,UUID spaceId,UUID principalId,long membershipVersion) {}
 record Preference(UUID groupId,UUID spaceId,UUID recipientId,long version,long membershipVersion,boolean enabled,long enabledAfter,String updatedAt) {}
 record Notice(UUID notificationId,UUID groupId,UUID spaceId,UUID recipientId,long membershipVersion,long version,boolean read,String state,UUID sourceEventId,String kind,UUID studyId,UUID assignmentId,UUID submissionId,long submissionVersion,UUID sourceAggregateId,long sourceVersion,long sourceOccurredAt,String deliveredAt,String updatedAt) {}
 record Revision(UUID revisionId,long version,Notice snapshot) {}
 record PreferenceRevision(UUID revisionId,long version,Preference snapshot) {}
 record Page(List<Notice> items,String nextAfter) {}
 private final JdbcTemplate db;private final TransactionTemplate tx;private final Clock clock;private final UuidV7 ids;private final JsonMapper json=JsonMapper.builder().build();
 GroupReviewStore(DataSource ds,Clock clock){db=new JdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));tx.setTimeout(15);this.clock=clock;ids=new UuidV7(clock);}
 private static ResponseStatusException fail(int status){return new ResponseStatusException(HttpStatus.valueOf(status),"Group notifications unavailable or changed");}
 private void lock(UUID group,UUID recipient){db.queryForObject("SELECT pg_advisory_xact_lock(?)",Object.class,group.getMostSignificantBits()^group.getLeastSignificantBits()^recipient.getMostSignificantBits()^recipient.getLeastSignificantBits());}
 boolean seeded(){return Boolean.TRUE.equals(db.queryForObject("SELECT seeded FROM group_review_runtime WHERE singleton",Boolean.class));}
 void seededNow(){db.update("UPDATE group_review_runtime SET seeded=true WHERE singleton");}
 Preference preference(Access a){var rows=db.query("SELECT snapshot::text FROM group_review_preference WHERE group_id=? AND recipient_id=?",(rs,n)->json.readValue(rs.getString(1),Preference.class),a.groupId(),a.principalId());if(rows.isEmpty())return new Preference(a.groupId(),a.spaceId(),a.principalId(),0,a.membershipVersion(),false,0,null);var p=rows.getFirst();if(!p.spaceId().equals(a.spaceId()))throw fail(404);return p.membershipVersion()==a.membershipVersion()?p:new Preference(a.groupId(),a.spaceId(),a.principalId(),p.version(),a.membershipVersion(),false,0,null);}
 Preference preference(Access a,long expected,boolean enabled,String trace){return tx.execute(s->{lock(a.groupId(),a.principalId());var old=preference(a);if(expected!=old.version())throw fail(412);if(old.enabled()==enabled)return old;var now=clock.instant();var p=new Preference(a.groupId(),a.spaceId(),a.principalId(),old.version()+1,a.membershipVersion(),enabled,enabled?Math.addExact(now.toEpochMilli(),1):0,now.toString());String raw=json.writeValueAsString(p);db.update("INSERT INTO group_review_preference VALUES (?,?,?,?,?,?,?,?::jsonb) ON CONFLICT(group_id,recipient_id) DO UPDATE SET version=EXCLUDED.version,membership_version=EXCLUDED.membership_version,enabled=EXCLUDED.enabled,enabled_after=EXCLUDED.enabled_after,snapshot=EXCLUDED.snapshot",a.groupId(),a.principalId(),a.spaceId(),p.version(),a.membershipVersion(),enabled,p.enabledAfter(),raw);db.update("INSERT INTO group_review_preference_revision VALUES (?,?,?,?,?::jsonb)",ids.next(),a.groupId(),a.principalId(),p.version(),raw);var payload=GroupReviewPreferenceV1.newBuilder().setGroupId(a.groupId().toString()).setRecipientId(a.principalId().toString()).setMembershipVersion(a.membershipVersion()).setVersion(p.version()).setEnabled(enabled).setEnabledAfterEpochMillis(p.enabledAfter()).setUpdatedAt(p.updatedAt()).build();event(a.spaceId(),a.principalId(),a.principalId(),"GroupReviewPreference","GroupReviewPreferenceChanged",trace,payload.toByteArray());return p;});}
 boolean accept(ReviewSignal.Signal signal){var v=ReviewSignal.validate(signal);return Boolean.TRUE.equals(tx.execute(s->{lock(v.groupId(),v.recipientId());var existing=db.queryForList("SELECT event_id,payload_hash FROM group_review_receipt WHERE event_id=? OR (aggregate_id=? AND source_version=?)",v.eventId(),v.aggregateId(),v.sourceVersion());if(!existing.isEmpty()){if(existing.size()!=1||!v.eventId().equals(existing.getFirst().get("event_id"))||!v.payloadHash().equals(existing.getFirst().get("payload_hash")))throw ReviewSignal.bad();return false;}var prefs=db.query("SELECT snapshot::text FROM group_review_preference WHERE group_id=? AND recipient_id=?",(rs,n)->json.readValue(rs.getString(1),Preference.class),v.groupId(),v.recipientId());var p=prefs.isEmpty()?null:prefs.getFirst();String capability=v.kind().startsWith("FEEDBACK_")?"feedback-retraction":v.kind().startsWith("GRADE_")?"grade-retraction":null;long cutoff=capability==null?0:db.queryForObject("SELECT enabled_after FROM group_review_source_activation WHERE source=?",Long.class,capability);String decision=v.occurredAt()<cutoff?"BEFORE_SOURCE_ACTIVATION":v.actorId().equals(v.recipientId())||v.kind().equals("RESUBMISSION_RESOLVED")?"SELF_OR_RESOLVED":p==null||!p.enabled()?"DISABLED":!p.spaceId().equals(v.spaceId())?"SCOPE_MISMATCH":v.occurredAt()<p.enabledAfter()?"BEFORE_CONSENT":"DELIVERED";if(decision.equals("SCOPE_MISMATCH"))throw ReviewSignal.bad();db.update("INSERT INTO group_review_receipt VALUES (?,?,?,?,?)",v.eventId(),v.payloadHash(),v.aggregateId(),v.sourceVersion(),decision);if(!decision.equals("DELIVERED"))return false;String now=clock.instant().toString();var n=new Notice(ids.next(),v.groupId(),v.spaceId(),v.recipientId(),p.membershipVersion(),1,false,"ACTIVE",v.eventId(),v.kind(),v.studyId(),v.assignmentId(),v.submissionId(),v.submissionVersion(),v.aggregateId(),v.sourceVersion(),v.occurredAt(),now,now);db.update("INSERT INTO group_review_notification VALUES (?,?,?,?,?,?,1,false,'ACTIVE',?::jsonb)",n.notificationId(),n.groupId(),n.spaceId(),n.recipientId(),n.membershipVersion(),n.sourceEventId(),json.writeValueAsString(n));revision(n,v.actorId(),v.traceId(),"GroupReviewNotificationCreated");return true;}));}
 private void revision(Notice n,UUID actor,String trace,String type){db.update("INSERT INTO group_review_revision VALUES (?,?,?,?::jsonb)",ids.next(),n.notificationId(),n.version(),json.writeValueAsString(n));var p=GroupReviewNotificationV1.newBuilder().setNotificationId(n.notificationId().toString()).setGroupId(n.groupId().toString()).setRecipientId(n.recipientId().toString()).setMembershipVersion(n.membershipVersion()).setVersion(n.version()).setRead(n.read()).setState(n.state()).setSourceEventId(n.sourceEventId().toString()).setChangeKind(n.kind()).setStudyId(n.studyId().toString()).setAssignmentId(n.assignmentId().toString()).setSubmissionId(n.submissionId().toString()).setSubmissionVersion(n.submissionVersion()).setSourceAggregateId(n.sourceAggregateId().toString()).setSourceVersion(n.sourceVersion()).setSourceOccurredAtEpochMillis(n.sourceOccurredAt()).setDeliveredAt(n.deliveredAt()).setUpdatedAt(n.updatedAt()).build();event(n.spaceId(),n.notificationId(),actor,"GroupReviewNotification",type,trace,p.toByteArray());}
 private void event(UUID space,UUID aggregate,UUID actor,String aggregateType,String type,String trace,byte[] payload){if(trace==null||!trace.matches("[0-9a-f]{32}")||trace.equals("0".repeat(32)))throw ReviewSignal.bad();var id=ids.next();var now=clock.instant();var e=GroupReviewEnvelopeV1.newBuilder().setEventId(id.toString()).setEventType(type).setEventVersion(1).setOccurredAtEpochMillis(now.toEpochMilli()).setProducer("notification-service").setAggregateType(aggregateType).setAggregateId(aggregate.toString()).setSpaceId(space.toString()).setActorId(actor.toString()).setTraceId(trace).setPayload(com.google.protobuf.ByteString.copyFrom(payload)).build();db.update("INSERT INTO outbox_event(id,aggregatetype,aggregateid,type,timestamp,trace_id,schema_group,schema_artifact,schema_version,payload) VALUES (?,'group-review',?,?,?,?,'notification','group-review-events','1',?)",id,aggregate,type,Timestamp.from(now),trace,e.toByteArray());}
 Notice get(Access a,UUID id){var rows=db.query("SELECT snapshot::text FROM group_review_notification WHERE notification_id=? AND group_id=? AND space_id=? AND recipient_id=? AND membership_version=?",(rs,n)->json.readValue(rs.getString(1),Notice.class),id,a.groupId(),a.spaceId(),a.principalId(),a.membershipVersion());if(rows.isEmpty())throw fail(404);return rows.getFirst();}
 Notice change(Access a,UUID id,long expected,Boolean read,boolean retire,String trace){return tx.execute(s->{lock(a.groupId(),a.principalId());var old=get(a,id);if(old.version()!=expected)throw fail(412);if(retire&&old.state().equals("RETIRED")||!retire&&old.read()==read)return old;var n=new Notice(id,old.groupId(),old.spaceId(),old.recipientId(),old.membershipVersion(),old.version()+1,read==null?old.read():read,retire?"RETIRED":old.state(),old.sourceEventId(),old.kind(),old.studyId(),old.assignmentId(),old.submissionId(),old.submissionVersion(),old.sourceAggregateId(),old.sourceVersion(),old.sourceOccurredAt(),old.deliveredAt(),clock.instant().toString());db.update("UPDATE group_review_notification SET version=?,is_read=?,state=?,snapshot=?::jsonb WHERE notification_id=?",n.version(),n.read(),n.state(),json.writeValueAsString(n),id);revision(n,a.principalId(),trace,retire?"GroupReviewNotificationRetired":"GroupReviewNotificationReadChanged");return n;});}
 Page list(Access a,String state,String read,String after,int limit){if(!Set.of("ACTIVE","RETIRED").contains(state)||!Set.of("ALL","READ","UNREAD").contains(read)||limit<1||limit>100)throw fail(400);UUID last=new UUID(0,0);String scope=a.groupId()+":"+a.spaceId()+":"+a.principalId()+":"+a.membershipVersion()+":"+state+":"+read+":";if(after!=null)try{String value=new String(Base64.getUrlDecoder().decode(after),StandardCharsets.UTF_8);if(!Base64.getUrlEncoder().withoutPadding().encodeToString(value.getBytes(StandardCharsets.UTF_8)).equals(after)||!value.startsWith(scope))throw fail(400);last=ReviewSignal.id(value.substring(scope.length()));}catch(RuntimeException e){throw fail(400);}var args=new ArrayList<Object>(List.of(a.groupId(),a.spaceId(),a.principalId(),a.membershipVersion(),state,last));String filter=read.equals("ALL")?"":" AND is_read="+read.equals("READ");args.add(limit+1);var rows=db.query("SELECT snapshot::text FROM group_review_notification WHERE group_id=? AND space_id=? AND recipient_id=? AND membership_version=? AND state=? AND notification_id>?"+filter+" ORDER BY notification_id LIMIT ?",(rs,n)->json.readValue(rs.getString(1),Notice.class),args.toArray());var items=List.copyOf(rows.subList(0,Math.min(limit,rows.size())));return new Page(items,rows.size()>limit?Base64.getUrlEncoder().withoutPadding().encodeToString((scope+items.getLast().notificationId()).getBytes(StandardCharsets.UTF_8)):null);}
 List<Revision> history(Access a,UUID id,long before,int limit){get(a,id);if(before<1||limit<1||limit>10)throw fail(400);return db.query("SELECT revision_id,version,snapshot::text FROM group_review_revision WHERE notification_id=? AND version<? ORDER BY version DESC LIMIT ?",(rs,n)->new Revision(rs.getObject(1,UUID.class),rs.getLong(2),json.readValue(rs.getString(3),Notice.class)),id,before,limit);}
 List<PreferenceRevision> preferenceHistory(Access a,long before,int limit){if(before<1||limit<1||limit>10)throw fail(400);return db.query("SELECT revision_id,version,snapshot::text FROM group_review_preference_revision WHERE group_id=? AND recipient_id=? AND version<? ORDER BY version DESC LIMIT ?",(rs,n)->new PreferenceRevision(rs.getObject(1,UUID.class),rs.getLong(2),json.readValue(rs.getString(3),Preference.class)),a.groupId(),a.principalId(),before,limit);}
}
